namespace RonSijm.FluidHumidifier.Factories.MediaTailor;

public class FunctionFactory(string resourceName = null, Action<Humidifier.MediaTailor.Function> factoryAction = null) : ResourceFactory<Humidifier.MediaTailor.Function>(resourceName)
{

    internal InnerFunctionAwsServiceRequestConfigurationFactory AwsServiceRequestConfigurationFactory { get; set; }

    internal InnerFunctionConcurrentExecutorConfigurationFactory ConcurrentExecutorConfigurationFactory { get; set; }

    internal InnerFunctionSequentialExecutorConfigurationFactory SequentialExecutorConfigurationFactory { get; set; }

    internal InnerFunctionVastRequestConfigurationFactory VastRequestConfigurationFactory { get; set; }

    internal InnerFunctionHttpRequestConfigurationFactory HttpRequestConfigurationFactory { get; set; }

    internal InnerFunctionCustomOutputConfigurationFactory CustomOutputConfigurationFactory { get; set; }

    protected override Humidifier.MediaTailor.Function Create()
    {
        var functionResult = CreateFunction();
        factoryAction?.Invoke(functionResult);

        return functionResult;
    }

    private Humidifier.MediaTailor.Function CreateFunction()
    {
        var functionResult = new Humidifier.MediaTailor.Function
        {
            GivenName = InputResourceName,
        };

        return functionResult;
    }
    public override void CreateChildren(Humidifier.MediaTailor.Function result)
    {
        base.CreateChildren(result);

        result.AwsServiceRequestConfiguration ??= AwsServiceRequestConfigurationFactory?.Build();
        result.ConcurrentExecutorConfiguration ??= ConcurrentExecutorConfigurationFactory?.Build();
        result.SequentialExecutorConfiguration ??= SequentialExecutorConfigurationFactory?.Build();
        result.VastRequestConfiguration ??= VastRequestConfigurationFactory?.Build();
        result.HttpRequestConfiguration ??= HttpRequestConfigurationFactory?.Build();
        result.CustomOutputConfiguration ??= CustomOutputConfigurationFactory?.Build();
    }

} // End Of Class

